log.raw:
{
  "understanding": {
    "purpose": "2023년과 2024년의 주요 아파트 실거래가 범위를 단지와 전용면적별로 비교하는 표다.",
    "reading": "독자는 단지명으로 행을 찾고 면적을 확인한 뒤, 같은 행에서 연도별 최저가와 최고가를 비교한다. 단지명이 여러 줄로 늘어나면 같은 행의 다른 셀에 생기는 높이를 활용할 수 있지만, 이름이 지나치게 잘리면 행을 찾기 어렵다.",
    "groups": [
      "1열과 2열은 각각 단지와 면적을 식별한다.",
      "3~4열과 5~6열은 각각 한 해의 최저가와 최고가를 묶는다.",
      "3~6열은 같은 역할의 가격 열이므로 비슷한 폭과 일정한 리듬이 비교에 도움이 된다."
    ],
    "keep_intact": [
      "전용면적의 숫자와 소수",
      "가격의 숫자와 쉼표로 구분된 자리",
      "가능한 한 단지명의 알아볼 수 있는 부분"
    ],
    "may_wrap": [
      "단지명은 단어 경계에서 여러 줄로 나뉠 수 있다.",
      "헤더는 의미를 유지하는 범위에서 줄바꿈할 수 있다."
    ]
  },
  "designs": [
    {
      "name": "A",
      "widths": [45, 66, 62, 62, 62, 62],
      "idea": "면적과 가격의 가장 긴 끊기지 않는 값을 수용하고 네 가격 열을 균등하게 유지하되 단지명에 많은 줄바꿈을 허용한다."
    },
    {
      "name": "B",
      "widths": [50, 61, 62, 62, 62, 62],
      "idea": "가격 열의 균형을 유지하면서 면적 열에서 5px을 단지명에 옮겨 행 식별을 돕지만 가장 긴 면적 값은 숫자 중간에서 끊길 수 있다."
    },
    {
      "name": "C",
      "widths": [55, 64, 60, 60, 60, 60],
      "idea": "단지명에 더 많은 폭을 주고 가격 열을 균등하게 유지하지만 면적과 일부 가격의 긴 숫자가 끊길 수 있어 비교의 정확성이 떨어질 위험이 있다."
    }
  ]
}
